MATCH (p:Product)-[:IN_SUBCATEGORY]->(:Subcategory)-[:IN_CATEGORY]->(:Category {name: 'Bikes'})
WHERE EXISTS {
  MATCH (p)<-[:HAS_LINE]-(o:SalesOrder)-[:IN_TERRITORY]->(:Territory {name: 'France'})
