}
AND NOT EXISTS {
  MATCH (p)<-[:HAS_LINE]-(o:SalesOrder)-[:IN_TERRITORY]->(:Territory {name: 'Germany'})
  WHERE o.order_date.year = 2023
}
RETURN p.product_number AS product_number
