MATCH (p:Product)-[:IN_SUBCATEGORY]->(:Subcategory)-[:IN_CATEGORY]->(:Category {name: 'Bikes'})
MATCH (so:SalesOrder)-[:HAS_LINE]->(p)
WHERE so.order_date.year = 2023
WITH p, collect(DISTINCT so) AS orders
WHERE ALL(so IN orders WHERE EXISTS {
    MATCH (so)-[:IN_TERRITORY]->(:Territory {name: 'Southeast'})
}) AND NONE(so IN orders WHERE EXISTS {
    MATCH (so)-[:IN_TERRITORY]->(:Territory {name: 'United Kingdom'})
})
RETURN p.product_number AS product_number
